  @surface #unrelated_surface { type:nurbs; degree-u:1; degree-v:1; knots-u:[0,0,1,1]; knots-v:[0,0,1,1]; control-points:[[[-0,0,7],[-0,2,7]],[[4,0,7],[4,2,7]]]; weights:[[1,1],[1,1]]; }
